import {
  TextField as AriaTextField,
  Label,
  TextArea,
  Text,
  FieldError,
} from "react-aria-components";
import type {
  TextFieldProps as AriaTextFieldProps,
  ValidationResult,
} from "react-aria-components";
import type { ReactNode, Ref } from "react";
import "./Textarea.css";

type TextareaSize = "small" | "medium" | "large";

export interface TextareaProps extends Omit<AriaTextFieldProps, "className" | "children"> {
  /**
   * Size axis. Changes padding/font.
   *
   * @default "medium"
   */
  size?: TextareaSize;
  /** Field label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Supporting description below the input. */
  description?: string;
  /** Message shown when validation fails (visible in the isInvalid state). */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** textarea placeholder. */
  placeholder?: string;
  /** textarea rows. */
  rows?: number;
  /** Additional class (optional). sd-textarea is always preserved. */
  className?: string;
  /** Forwarded to the underlying <textarea> DOM node. */
  ref?: Ref<HTMLTextAreaElement>;
}

export function Textarea({
  size = "medium",
  label,
  contextualHelp,
  description,
  errorMessage,
  placeholder,
  rows,
  className,
  ref,
  ...props
}: TextareaProps) {
  return (
    <AriaTextField
      {...props}
      className={className ? `sd-textarea ${className}` : "sd-textarea"}
    >
      {contextualHelp ? (
        <div className="sd-textarea__label-group">
          {label && <Label className={`sd-textarea__label sd-type-label-${size}`}>{label}</Label>}
          {contextualHelp}
        </div>
      ) : (
        label && <Label className={`sd-textarea__label sd-type-label-${size}`}>{label}</Label>
      )}
      <TextArea
        ref={ref}
        data-size={size}
        placeholder={placeholder}
        rows={rows}
        className={`sd-textarea__input sd-type-body-${size}`}
      />
      {description && (
        <Text slot="description" className={`sd-textarea__description sd-type-caption-${size}`}>
          {description}
        </Text>
      )}
      <FieldError className={`sd-textarea__error sd-type-caption-${size}`}>{errorMessage}</FieldError>
    </AriaTextField>
  );
}

.sd-textarea {
  --sd-textarea-input-background-current: var(--sd-textarea-input-background);
  display: flex;
  flex-direction: column;
  gap: var(--sd-textarea-gap);
}
.sd-textarea[data-readonly] {
  --sd-textarea-input-background-current: var(--sd-textarea-input-background-readonly);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-textarea__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-textarea-label-group-gap);
}

.sd-textarea__label {
  padding-inline: var(--sd-textarea-text-padding-inline);
  color: var(--sd-textarea-label-foreground);
}

.sd-textarea__input {
  width: 100%;
  min-height: var(--sd-textarea-input-min-height);
  background: var(--sd-textarea-input-background-current);
  color: var(--sd-textarea-input-foreground);
  border: var(--sd-textarea-input-border-width) solid var(--sd-textarea-input-border);
  border-radius: var(--sd-textarea-input-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* Suppress the UA focus outline — the component draws its own indicator below
     (`[data-focused]`: border-color + ring). Without this the browser stacks `outline: auto` on top
     of that ring, so the field shows TWO rings, and because `outline: auto` uses
     `-webkit-focus-ring-color` the extra one takes the OS accent colour — it renders orange on a Mac
     set to an orange accent, blue elsewhere. Every other field in the family already resets it;
     this, TextField and ColorField were the three that did not. */
  outline: none;
  resize: vertical;
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-textarea__input::placeholder {
  color: var(--sd-textarea-input-placeholder);
}

.sd-textarea__input[data-size="small"] {
  padding: var(--sd-textarea-input-padding-block-small) var(--sd-textarea-input-padding-inline-small);
}
.sd-textarea__input[data-size="medium"] {
  padding: var(--sd-textarea-input-padding-block-medium) var(--sd-textarea-input-padding-inline-medium);
}
.sd-textarea__input[data-size="large"] {
  padding: var(--sd-textarea-input-padding-block-large) var(--sd-textarea-input-padding-inline-large);
}

.sd-textarea__input[data-hovered] {
  border-color: var(--sd-textarea-input-border-hover);
}
.sd-textarea__input[data-focused] {
  border-color: var(--sd-textarea-input-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-textarea__input[data-invalid] {
  border-color: var(--sd-textarea-input-border-invalid);
}
.sd-textarea__input[data-invalid][data-focused] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-textarea-input-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-textarea__input[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-textarea__description {
  padding-inline: var(--sd-textarea-text-padding-inline);
  color: var(--sd-textarea-description-foreground);
}
.sd-textarea__error {
  padding-inline: var(--sd-textarea-text-padding-inline);
  color: var(--sd-textarea-error-foreground);
}
